package com.bank.security;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StringDemo {
    private static final Logger log = Logger.getLogger(StringDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        String accountId = "SAV2001";       // immutable literal, interned
        AccountMasker masker = new AccountMasker();

        String masked = masker.mask(accountId);
        log.info(() -> "Original id (unchanged): " + accountId);
        log.info(() -> "Masked id (new String):  " + masked);

        // Correct comparison: equals, not ==
        String fromForm = new String("SAV2001");   // different object, same content
        boolean same = masker.matches(accountId, fromForm);
        log.info(() -> "equals() comparison result: " + same);
        log.info(() -> "== comparison would be: " + (accountId == fromForm));
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
