package com.bank.security;

class AccountMasker {

    // Returns a NEW masked String; the original is never modified.
    String mask(String accountId) {
        if (accountId == null || accountId.length() < 2) {
            throw new IllegalArgumentException("account id too short to mask");
        }
        String prefix = accountId.substring(0, 2);   // new String "SA"
        return prefix + "XXXX";                       // new String "SAXXXX"
    }

    // Correct content comparison for Strings.
    boolean matches(String a, String b) {
        if (a == null) return b == null;
        return a.equals(b);                           // compare characters, not identity
    }
}
